<h2>Convert RCF and RPM</h2><p class="lead">Convert centrifuge speed between RPM and relative centrifugal force using rotor radius.</p><div class="notice">Protocols should preferably specify RCF because the same RPM produces different force in rotors with different radii.</div><div class="form-grid"><div class="field"><label for="mode">Convert</label><select id="mode"><option value="rpm2rcf" selected>RPM → RCF (×g)</option><option value="rcf2rpm">RCF (×g) → RPM</option></select></div><div class="field"><label for="value">RPM or RCF value</label><input id="value" type="number" value="5000" min="0" step="any"></div><div class="field"><label for="radius">Rotor radius (cm)</label><input id="radius" type="number" value="10" min="0.0001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>RPM</span><strong id="rpm">—</strong></div><div class="metric"><span>RCF (×g)</span><strong id="rcf">—</strong></div><div class="metric"><span>Radius used</span><strong id="radiusout">—</strong></div><div class="metric"><span>Rotor-tip speed</span><strong id="tip">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('rpm').textContent='—';$('rcf').textContent='—';$('radiusout').textContent='—';$('tip').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const mode=$('mode').value,v=num('value'),r=num('radius');if(!(v>=0&&r>0))throw 0;let rpm,rcf;if(mode==='rpm2rcf'){rpm=v;rcf=1.118e-5*r*rpm*rpm}else{rcf=v;rpm=Math.sqrt(rcf/(1.118e-5*r))}const speed=2*Math.PI*(r/100)*rpm/60;$('rpm').textContent=fmt(rpm,2)+' rpm';$('rcf').textContent=fmt(rcf,2)+' ×g';$('radiusout').textContent=fmt(r,3)+' cm';$('tip').textContent=fmt(speed,2)+' m/s';$('note').textContent='Thermo Fisher states RCF = 1.118×10⁻⁵ × radius(cm) × RPM². Use the rotor radius definition required by your centrifuge protocol.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
